from loading.namespaces import NS


def allowances(line):
    for ac in line.findall('cac:AllowanceCharge', NS):
        sign = 1 if ac.findtext('cbc:ChargeIndicator', namespaces=NS) == 'true' else -1
        yield sign * Decimal(ac.findtext('cbc:Amount', namespaces=NS))

