from collections import defaultdict

from report.errors import ValidationError


def check_br_co_14(subtotals, tax_total):
    by_category = defaultdict(int)
    for s in subtotals:
        by_category[(s['category'], s['percent'])] += s['tax']
    if sum(by_category.values()) != tax_total:
        yield ValidationError('BR-CO-14', 'tax total differs from subtotals', '/Invoice/cac:TaxTotal')

