from collections import OrderedDict


class LRU(OrderedDict):
    def __init__(self, size=512):
        super().__init__()
        self.size = size

    def put(self, key, value):
        self[key] = value
        self.move_to_end(key)
        if len(self) > self.size:
            self.popitem(last=False)
